registerRefData('nsw-cond-n-1636',{"id":1636,"pan":null,"ref":"MA2021/00192","address":"1 Laman Street Cooks Hill 2300","description":"Sec 4.55(2) modification to DA2010/1278","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":null,"notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPSHCC-79!20211206T033147.929 GMT","sha256":"8dd308c92f25247a6cff1318cef80ea02f137ef0262e5e168f4892adb307a098","pages":39,"layout":"numbered","n":110,"fetched_at":"2026-08-16T23:19:06+00:00","file":"n/1636.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/sec-4552-modification-da20101278","lga":"NEWCASTLE","conditions":[{"label":"1","code":null,"number":"1","title":"PANEL REF - LGA - DA NO. PPSHCC-79 - Newcastle - MA2021/00192","text":"","stage":"general","stage_basis":"heading","page":4},{"label":"2","code":null,"number":"2","title":"PROPOSED DEVELOPMENT Section 4.55(2) modification to DA2010/1278 - community facility and","text":"retail (redevelopment of Newcastle Art Gallery) - change to floor plans,\nelevations and landscape including deletion of Darby Street retail premises","stage":"general","stage_basis":"heading","page":4},{"label":"3","code":null,"number":"3","title":"STREET ADDRESS 1 Laman St, Cooks Hill","text":"","stage":"general","stage_basis":"heading","page":4},{"label":"4","code":null,"number":"4","title":"APPLICANT/OWNER Newcastle City Council","text":"","stage":"general","stage_basis":"heading","page":4},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT Section 4.55(2) Modification Application","stage":"general","stage_basis":"heading","page":4},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n Environmental planning instruments:\no State Environmental Planning Policy (State and Regional\nDevelopment) 2011\no State Environmental Planning Policy (Infrastructure) 2007\no State Environmental Planning Policy (Vegetation in Non-Rural\nAreas) 2017\no State Environmental Planning Policy No. 55 - Remediation of Land\no State Environmental Planning Policy (Coastal Management) 2018\no Newcastle Local Environmental Plan 2012\n Draft environmental planning instruments\n Development control plans:\no Newcastle Development Control Plan 2012\no City of Newcastle’s Community Participation Plan 2019\n Planning agreements: Nil\n Provisions of the Environmental Planning and Assessment Regulation\n2000:\n Coastal zone management plan:\n The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and economic\nimpacts in the locality\n The suitability of the site for the development\n Any submissions made in accordance with the Environmental Planning\nand Assessment Act 1979 or regulations\n The public interest, including the principles of ecologically sustainable\ndevelopment","stage":"general","stage_basis":"heading","page":4},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL\n Council assessment report: 10 November 2021\n Council assessment memorandum: 25 November 2021\n Written submissions during public exhibition: nil (therefore no public\nmeeting required)","stage":"general","stage_basis":"heading","page":4},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS AND","text":"SITE INSPECTIONS BY THE\nPANEL\n Briefing: 21 July 2021\no Panel members: Alison McCabe (Chair), Juliet Grant and Sandra\nHutton\no Council assessment staff: Elle Durrant, Amy Ryan and Tracey\nWebb\no Department staff: Leanne Harris, Carolyn Hunt and Lisa Foley\n Site inspections:\no Sandra Hutton: 1 November 2021\no Juliet Grant: 1 November 2021\n Final briefing to discuss Council’s recommendation: 17 November\n2021\no Panel members: Alison McCabe (Chair), Juliet Grant and Sandra\nHutton\no Council assessment staff: Elle Durrant, Amy Ryan, Isabelle\nRowlatt, Matthew Swan, Brian Cameron, Daniel O’Brien and\nOlivia Magrath\no Department staff: Leanne Harris and Lisa Foley\n Applicant Briefing: 17 November 2021\no Panel members: Alison McCabe (Chair), Juliet Grant and Sandra\nHutton\no Council assessment staff: Elle Durrant, Amy Ryan, Isabelle\nRowlatt, Matthew Swan, Brian Cameron, Daniel O’Brien and\nOlivia Magrath\no Department staff: Leanne Harris and Lisa Foley\no Applicant representatives: Matthew Bennett, Kerry Clare, Dane\nEverett, Penelope Hoyle Philip, Alaine Roff and Naomi Ryan\nNote: Applicant briefing was requested to respond to the\nrecommendation in the Council assessment report","stage":"general","stage_basis":"heading","page":4},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION Approval","stage":"general","stage_basis":"heading","page":5},{"label":"10","code":null,"number":"10","title":"DRAFT CONDITIONS Attached to the Council assessment report","text":"INSTRUMENT OF MODIFICATION\nModification Application No: MA2021/00192\nDevelopment Application No:\nDA2010/1278\nLand:\nLots 10, 11, 12, 13, 14 & 15, DP 1122031;\nLot 1, DP 63100;\nLot 1 DP 516670; and\nPt Lot 18, Sec G DP 978941\nProperty Address:","stage":"general","stage_basis":"heading","page":5},{"label":"1","code":null,"number":"1","title":"Laman Street Cooks Hill NSW 2300","text":"Development Consent:\nRedevelopment of Newcastle Art Gallery\nProposed Development: Sec 4.55(2) modification to DA2010/1278 - Community\nFacility and Retail (Redevelopment of Newcastle Art\nGallery) - change to floor plans, elevations and landscape\nincluding deletion of Darby Street retail premises.\nIn accordance with Section 4.55 of the Environmental Planning and Assessment Act 1979, Development\nConsent No. DA2010/1278 is to be modified by:\nInserting Condition No. 1A to read:\n1A The General Terms of Approval from state authorities must b e complied with prior to, during,\nand at the completion of the development. The General Terms of Approval are:\na) Subsidence Advisory NSW, ref: TBA21-00305 & TBA21-02116, da ted 12 October 2021\nA copy of the General Terms of Approval are attached to this determination notice.\n(Inserted under MA2021/00192)\nInserting Condition No. 1B to read:\n1B Development consent has not been granted to the following e lements of the proposal (as\nmarked in red on the approved plans):\na) Streets tree planting within Darby Street, including associ ated tree planting enclosures\nand paving works; and\nb) Low height planting within the Darby Street footway for the extent of any Bus Zone\nNote: Condition 3 requires low height planting within the Darby Street footway for the\nfrontage of the development excluding the extent of the Bus Zone.\nWorks not approved are to be excluded from documentation submit ted for a Construction\nCertificate application.\nSCHEDULE 2\n(Inserted under MA2021/00192)\nAmending Condition No. 2 to read:","stage":"general","stage_basis":"heading","page":6},{"label":"2","code":null,"number":"2","title":"","text":"The development is to be implemented in accordance with the p lans and supporting\ndocuments set out in the following table except where modified b y a n y c o n d i t i o n s o f t h i s\nconsent.\nPlan No./Supporting\nDocument\nReference/\nVersion\nPrepared by Dated\nDA-A-000\nTitle Sheet & Locality\nPlan\nRev K Smith & Tzannes in association\nwith Clare Design\n02/11/2021\nDA-A-010\nSite Demolition Plan\nRev G Smith & Tzannes in association\nwith Clare Design\n11/10/2021\nDA-A-011\nDemolition Plan Level\n1& Mezzanine\nRev F Smith & Tzannes in association\nwith Clare Design\n11/10/2021\nDA-A-012\nOverall Site Plan\nRev I Smith & Tzannes in association\nwith Clare Design\n11/10/2021\nDA-A-032\nLandscape Plan -\nCover Sheet\nRev B Smith & Tzannes in association\nwith Clare Design\n15/10/2021\nDA-A-033\nLandscape Plan -\nExisting Site Plan\nRev B Smith & Tzannes in association\nwith Clare Design\n15/10/2021\nDA-A-034\nLandscape Plan - Site\nMasterplan\nRev B Smith & Tzannes in association\nwith Clare Design\n15/10/2021\nDA-A-035\nLandscape Plan -\nLaman Street\nElevation\nRev B Smith & Tzannes in association\nwith Clare Design\n15/10/2021\nDA-A-036\nLandscape Plan -\nDarby Street Elevation\nRev C Smith & Tzannes in association\nwith Clare Design\n15/10/2021\nDA-A-037\nLandscape Plan -\nPlan Details (1)\nRev B Smith & Tzannes in association\nwith Clare Design\n11/10/2021\nDA-A-038\nPlan Details (2)\nRev C Smith & Tzannes in association\nwith Clare Design\n15/10/2021\nDA-A-039\nLandscape Plan -\nProposed Planting\nSpecies\nRev B Smith & Tzannes in association\nwith Clare Design\n11/10/2021\nDA-A-100\nProposed Lower\nGround Floor Plan\nRev M Smith & Tzannes in association\nwith Clare Design\n02/11/2021\nDA-A-101\nProposed Ground\nFloor Plan\nRev N Smith & Tzannes in association\nwith Clare Design\n02/11/2021\nDA-A-102\nProposed First Floor\nPlan\nRev K Smith & Tzannes in association\nwith Clare Design\n02/11/2021\nDA-A-103\nProposed Roof Plan\nRev I Smith & Tzannes in association\nwith Clare Design\n11/10/2021\nDA-A-200\nElevations (North &\nEast)\nRev J Smith & Tzannes in association\nwith Clare Design\n02/11/2021\nDA-A-201\nElevations (South &\nWest)\nRev J Smith & Tzannes in association\nwith Clare Design\n02/11/2021\nDA-A-202\nSections\nRev H Smith & Tzannes in association\nwith Clare Design\n02/11/2021\nDA-A-903\nMaterials and Colours\nRev D Smith & Tzannes in association\nwith Clare Design\n29/10/2021\nDA-A-910\nPerspective\nRev A Smith & Tzannes in association\nwith Clare Design\n02/11/2021\nSTZ-0196-ID1 1of2\nSignage\nIssue v1 Smith & Tzannes in association\nwith Clare Design\n29/10/2013\nSTZ-0196-ID1 2of2\nSignage\nIssue v1 Smith & Tzannes in association\nwith Clare Design\n29/10/2013\nIn the event of any inconsistency between conditions of this de velopment consent and the\nplans/supporting documents referred to above, the conditions of this development consent\nprevail.\n(Amended under MA2021/00192)\nAmending Condition No. 2A to read:\n2A. Additional details of the materials and finishes are to be submitted to the Development and\nBuilding Section of Council for approval prior to the issue of the Construction Certificate, and\nsuch details to be complied with and included in the details an d schedule(s) for the\nConstruction Certificate. Such details are to be consistent wi th the approved material and\ncolours (Drawing No. DA-A-903, prepared by Smith & Tzannes in a ssociation with Clare\nDesign, dated 29/10/2021) in type and quality.\n(Amended under MA2021/00192)\nAmending Condition No. 3 to read:","stage":"general","stage_basis":"heading","page":7},{"label":"3","code":null,"number":"3","title":"","text":"The Developer designing and constructing the following works in connection with the proposed\ndevelopment within the Darby Street and Queen Street public roa d reserve, adjacent to the\nsite, will provide at no cost to Council and in accordance with Council’s guidelines and design\nspecifications:\na) Footpath replacement to Council requirements\nb) Kerb and gutter replacement along Darby Street frontage\nc) New driveway crossing on Queen Street\nd) Associated drainage works\ne) Installation of low height planting such as shrubs, grasses, or ground covers to Council's\nrequirements within the Darby Street footway for the frontage o f the development site\nexcluding the extent of any Bus Zone. Each garden bed is to be 3m long and 600mm\nwide, offset 200mm from the Darby Street kerb. Spacing between garden beds is to be\n3m.\nf) The existing 3 metre long, 225mm size stormwater pipe downst ream of the existing kerb\ninlet pit at the corner of Laman and Darby Streets is to be upgraded to a 375mm pipe.\nEngineering and landscape design plans and specifications for t he works being undertaken\nwithin the public road reserve are required to be prepared by a suitably qualified practising civil\nengineer with experience and competence in the related field an d submitted to Council for\napproval pursuant to Section 138 of the Roads Act 1993 (NSW). T he consent must be\nobtained, or other satisfactory arrangements confirmed in writi ng from Council, before the\nissue of a Construction Certificate.\n(Amended under MA2021/00192)\nAmending Condition No. 7 to read:\n7 All stormwater runoff from the proposed development being man aged in accordance with the\nrequirements of the Section 7.06 ‘Stormwater’ of Newcastle Deve lopment Control Plan 2012\nand the associated Technical Manual and the latest issue of AS 3500.3 where applicable, as\nindicated on the stormwater management concept plan prepared by Arup (Job No. 278551,\nDrg. No. SK-H-001 (Drawings 1 to 7), dated 29.10.2021). Full de tails to be included in\ndocumentation for a Construction Certificate application.\n(Amended under MA2021/00192)\nDeleting Condition No. 15\nAmending Condition No. 16 to read:\n16. Prior to any ground disturbance works occurring on site, t he applicant must obtain an approved\nSection 140 application under the Heritage Act 1977 to undertak e archaeological excavation\nof the study area. The applicant must comply with all the appro val conditions of the Section\n140 approval. Full details are to be included in documentation for a Construction Certificate\napplication.\n(Amended under MA2021/00192)\nAmending Condition No. 17 to read:\n17. Prior to the work commencing and before the release of the Construction Certificate an archival\nrecord of the building, both internally and externally is to be made that is consistent with the\nNSW Heritage Office publications:\na) How to Prepare Archival Records of Heritage Items (1998); a nd\nb) Photographic Recording of Heritage Items using Film or Digi tal Capture (2006).\nThe archival record is to be submitted to Council for inclusion in the City Library collection prior\nto the issue of the Construction Certificate. Confirmation that the records have been submitted\nto Council shall be provided to the Principal Certifying Author ity prior to the issue of a\nConstruction Certificate.\n(Amended under MA2021/00192)\nAmending Condition No. 18 to read:\n18. The building floor level of the, plant room, main switch b oard room and communications area\nbeing set a minimum of 300mm above the local 1 in 100 year ARI flood level. Details to be\nindicated on plans for a Construction Certificate application.\n(Amended under MA2021/00192)\nInserting Condition No. 18A to read:\n18A. The proposed awning is to be designed in a manner that is consistent with Element 7.10 ‘Street\nAwnings and Balconies’ of the Newcastle Development Control Pla n 2012. Full details are to\nbe included in documentation for a Construction Certificate application.\n(Inserted under DA2010/1278.02 - 3 September 2012)\nInserting Condition No. 18B to read:\n18B The existing 3 metre long, 225mm size stormwater pipe downs tream of the existing kerb inlet\npit at the corner of Laman and Darby Streets is to be upgraded to a 375mm pipe.\nA separate application must be lodged and consent obtained fro m Council for all works within\nthe road reserve pursuant to Section 138 of the Roads Act 1993 (NSW). The consent must be\nobtained, or other satisfactory arrangements confirmed in writi ng from Council, before the\nissue of a Construction Certificate.\n(Inserted under MA2021/00192)\nInserting Condition No. 18C to read:\n18C The stormwater design is to ensure post-development stormwa ter flows do not exceed pre-\ndevelopment flows to both Queen Street and Darby Street in acco rdance with Element 7.06\n‘Stormwater’ of Newcastle Development Control Plan 2012. Full d etails are to be provided as\npart of a construction certificate application.\n(Inserted under MA2021/00192)\nInserting Condition No. 18D to read:\n18D The applicant is required to engage an electrical consultan t or contractor to complete an online\napplication to Ausgrid for the connection of the approved devel opment to the adjacent\nelectricity network infrastructure.\n(Inserted under MA2021/00192)\nInserting Condition No. 18E to read:\n18E Provision is to be made on the site for the installation of a ‘kiosk’ type electricity substation\nshould such be required by the electricity authority and any such ‘kiosk’ being located in public\nreserves and/or private land and are not to be located within r oad reserves. Any such\nsubstation is to be appropriately screened to ensure the visual amenity of the streetscape is\nmaintained. Full details are to be included in documentation fo r a Construction Certificate\napplication.\n(Inserted under MA2021/00192)\nInserting Condition No. 18F to read:\n18F A title search of the development site should be completed to check for existing electricity\neasements. If easements are present, Ausgrid must assess the pr oposed activity within the\neasement. Reference should be given to Ausgrid's “Living with E lectricity Easements”\nbrochure. Full details are to be included in documentation for a Construction Certificate\napplication.\n(Inserted under MA2021/00192)\nInserting Condition No. 18G to read:\n18G The internal floor level of the 'Lower Ground Floor' is not to be any lower than RL 7.4 AHD as\nindicated in the approved plans. Basement or similar structures below this level will require a\nseparate application to Council. Full details are to be include d in documentation for a\nConstruction Certificate application.\n(Inserted under MA2021/00192)\nAmending Condition No. 20 to read:\n20. A commercial type vehicular crossing up to 13.5m with appr opriate splays being constructed\nacross the public footway at the proposed driveway entrance/exi t at no cost to Council and in\naccordance with Crossing Standard Details A1300.\n(Amended under MA2021/00192)\nInserting Condition No. 21A to read:\n21A Any structure on or over the public road reserve, including balconies and awnings, is to be the\nsubject of a separate consent from Council, under Section 138 of the Roads Act 1993, prior to\ncommencement of work.\nNote: A separate approval from Council must be obtained for al l structures within the public\nroad reserve pursuant to Section 138 of the Roads Act 1993. For further information\ncontact Council’s Strategic Property and Fleet Management Services on 4974 2000 to\nrequest a Road Consent. A fee will be payable in this regard.\n(Inserted under DA2010/1278.02 - 3 September 2012)\nInserting Condition No. 21B to read:\n21B Prior to the commencement of any works within the public ro ad reserve, details shall be\nsubmitted with the Roads Act Application for the proposed awning, demonstrating compliance\nwith the following:\na) Appropriate lighting being provided for the carpark and ped estrian pathways in\naccordance with AS 1158 - Lighting and AS 4282 - Control of the Obtrusive Effects of\nOutdoor Lighting.\nb) The design of the awning is to include cutout segments (if needed) to accommodate\nstreet trees.\n(Inserted under DA2010/1278.02 - 3 September 2012)\nInserting Condition No. 53A to read:\n53A There are existing overhead electricity network assets in Q ueen and Darby Street, adjacent to\nthe development site. Workcover Code of Practice 2006 Work Near Overhead Powerlines\noutlines the minimum safety separation requirements between these mains/poles to structures\nwithin the development throughout the construction phase. Any r elocation of overhead mains\nrequired to maintain minimum safety clearances is at the cost of the person having the benefit\nof this consent.\n(Inserted under MA2021/00192)\nInserting Condition No. 53B to read:\n53B The development is in proximity to underground electricity assets. In addition to DBYD\nsearches a ground search is to be conducted to locate electrici ty assets immediately prior to\ncommencing work to check for updates of installed utilities. Du ring construction work is to be\nundertaken in accordance with Ausgrids’s Network Standard 156 - Working near or around\nunderground cables. Any alterations to Ausgrid’s underground el ectricity main will be\ncontestable works and funded by the person having the benefit of this consent.\n(Inserted under MA2021/00192)\nInserting Condition No. 53C to read:\n53C Prior to works commencing, all contractors and sub-contract ors are to undergo a site induction\nprovided by a suitably qualified heritage professional, which i s to include the significance of\nthe site and the relevant obligations under the Heritage Act 1977 and the National Parks and\nWildlife Act 1974.\n(Inserted under MA2021/00192)\nInserting Condition No. 53D to read:\n53D The development is to be undertaken in accordance with the recommendations in the Historical\nArchaeological Assessment and Statement of Heritage Impact prep ared by Austral\nArchaeology (dated 4 November 2021).\n(Inserted under MA2021/00192)\nInserting Condition No. 53E to read:\n53E If unanticipated suspected Aboriginal heritage items are un covered at any time throughout the\nlife of the project, excavation or disturbance of the area is t o stop immediately and Heritage\nNSW is to be notified in accordance with Section 89A of the National Parks and Wildlife Act\n1974 (NPW Act). Aboriginal objects in NSW are protected under the N PW Act. Unless the\nobjects are subject to a valid Aboriginal Heritage Impact Permi t, work must not recommence\nuntil approval to do so has been provided by Heritage NSW.\n(Inserted under MA2021/00192)\nInserting Condition No. 53F to read:\n53F Construction works are to be carried out in accordance with the recommendations of;\na) Report: Douglas Partners Pty Ltd (February 2021) Report on G roundwater Sampling\nR.001.Rev0; and\nb) Letter: Douglas Partners Pty Ltd (8 November 2021) Proposed Rainwater Tank.\nR.001.Rev0.\n(Inserted under MA2021/00192)\nInserting Condition No. 53G to read:\n53G Monitoring for volatile gases shall be conducted by a suita bly qualified and experienced\nenvironmental consultant during the excavations for the rainwat er tank. If volatile gases are\ndetected which exceed appropriate guidelines, works are to imme diately cease and advice is\nto be sought from the environmental consultant and recommendati ons in respect to the\nmanagement of health or environmental risk are to be implemente d in accordance with\nappropriate guidelines and legislation.\n(Inserted under MA2021/00192)\nAmending Condition No. 66 to read:\n66. The building floor level of the plant room, main switch bo ard room and communications area\nbeing set a minimum of 300mm above the local 1 in 100 year ARI flood level. The finished\nfloor levels are to be certified by a registered Surveyor prior to the placement of the floor\nmaterial and a copy of the Surveyor’s Certificate is to be forw arded to the Principal Certifying\nAuthority.\n(Amended under MA2021/00192)\nAmending Condition No. 67A to read:\n67A 17 suitable replacement trees either on/adjoining the subj ect site, or off site within a distance\nof 400 meters as measured from any point along the development site boundary, are required\nin order to replace the trees being removed as part of the development. All replacement trees\nare to be planted prior to the issue of an Occupation Certifica te, and a list provided to the\ncertifying authority.\n(Amended under MA2021/00192)\nAmending Condition No. 67B to read:\n67B The awning on the Darby Street, Queen Street and Laman Stre et frontages is required to be\nconstructed prior to the issue of the Occupation Certificate fo r the development the subject of\nthis consent.\n(Amended under DA2010/1278.02 - 3 September 2012)\nDeleting Condition No. 67C\nInserting Condition No. 67D to read:\n67D Prior to the release of the Occupation Certificate, the Applicant must demonstrate to the written\nsatisfaction of Council, that they have satisfied the requireme nts for lodging all final\narchaeological excavation reports required under any and all s. 140 applications under the\nHeritage Act 1977 which have been approved by the Heritage Council of NSW for this site.\n(Inserted under MA2021/00192)\nDeleting Condition No. 68\nAmending Condition No. 69 to read:\n69. The maximum number of patrons permitted within the café an d associated terrace area is to\nbe restricted to 100 persons in total. A sign must be displayed in a prominent position in the\ncafe stating the maximum number of patrons, as specified in the development consent, that\nare permitted in the café.\n(Amended under MA2021/00192)\nAmending Condition No. 70 to read:\n70. The hours of operation or trading of the premises are to b e not more than from:\nDAY START FINISH\nMonday 6am 10pm Same day\nTuesday 6am 10pm Same day\nWednesday 6am 10pm Same day\nThursday 6am 10pm Same day\nFriday 6am 10pm Same day\nSaturday 6am 10pm Same day\nSunday 6am 10pm Same day\nunless a separate application to vary the hours of operation or trading has been submitted to\nand approved by Council.\n(Amended under MA2021/00192)\nDeleting Condition No. 71\nDeleting Condition No. 74\nDeleting Condition No. 75\nDeleting Condition No. 76\nDeleting Condition No. 77\nDeleting Condition No. 78\nDeleting Condition No. 79\nInserting Condition No. 86A to read:\n86A Provision is to be made for regular maintenance to ensure t he continuing structural integrity\nand attractive appearance of the street awning. A maintenance p lan is to be developed and\ninclude:\na) annual inspection of structural components\nb) repainting, as required\nc) regular maintenance to guttering and downpipes\nd) regular cleaning and replacement of defective lighting, adv ertising or other deteriorated\ncomponents of the awning\ne) regular cleaning of awning glazing, where installed.\n(Inserted under DA2010/1278.02 - 3 September 2012)\nInserting Condition No. 96 to read:\n96 If archaeological deposits or relics not identified and cons idered in the supporting documents\nfor this consent are discovered, work must cease in the affecte d area(s) and the Heritage\nCouncil of NSW notified. Additional assessment and approval may be required prior to works\ncontinuing in the affected area(s) based on the nature of the discovery.\nNote: The Heritage Council of NSW can be contacted on 02 9873 8 500 or\nheritagemailbox@environment.nsw.gov.au. A ‘relic’ is any deposi t, object or material\nevidence that relates to the settlement of New South Wales, not being Aboriginal\nsettlement, and is of State or local significance. It is an offence under the provisions of\nthe Heritage Act 1977 (NSW) for a person to disturb or excavate any land on which the\nperson has discovered a relic except in accordance with a gazet ted exemption or an\nexcavation permit issued by the Heritage Council of NSW.\n(Inserted under MA2021/00192)\nInserting Schedule 2 to read:\nSCHEDULE 2\nSUBSIDENCE ADVISORY NSW\n(Inserted under MA2021/00192)\nInserting Schedule 3 to read:\nSCHEDULE 3\nREASONS FOR THE DETERMINATION & CONSIDERATION OF COMMUNITY VIEWS\nThe determination decision was reached for the following reasons:\n The proposed development, subject to the recommended conditions, is consistent with the objectives\nof the applicable environmental planning instruments, being; Newcastle Local Environmental Plan\n2012 and applicable State Environmental Planning Policies.\n The proposed development is, subject to the recommended conditions, consistent with the objectives\nof the Newcastle Development Control Plan 2012.\n The proposed development is considered to be of an appropriate scale and form for the site and the\ncharacter of the locality.\n The proposed development has appropriate management and mitigat ion of impacts through\nconditions of consent.\n The proposed development, subject to the recommended conditions , will not result in unacceptable\nadverse impacts upon the natural or built environments.\n The proposed development is a suitable and planned use of the site and its approval is within the public\ninterest.\n(Inserted under MA2021/00192)\nSCHEDULE OF CONDITIONS\nApplication No: MA2021/00192\nLand:\nLots 10, 11, 12, 13, 14 & 15, DP 1122031;\nLot 1, DP 63100;\nLot 1 DP 516670; and\nPt Lot 18, Sec G DP 978941\nProperty Address:","stage":"general","stage_basis":"heading","page":8},{"label":"1","code":null,"number":"1","title":"Laman Street Cooks Hill NSW 2300","text":"Proposed Development: Sec 4.55(2) modification to DA2010/1278 - Community\nFacility and Retail (Redevelopment of Newcastle Art\nGallery) - change to floor plans, elevations and landscape\nincluding deletion of Darby Street retail premises.","stage":"general","stage_basis":"heading","page":19},{"label":"1","code":null,"number":"1","title":"","text":"The conditions of this consent have been imposed in accordanc e with Section 80A of the\nEnvironmental Planning and Assessment Act 1979 (NSW). The conditions relate to any matter\nreferred to in Section 79C(1) of relevance to the development t he subject of the consent and\nare imposed to ensure that the development is undertaken in an orderly manner, with\nacceptable impacts on the natural and built environment.\nADMINISTRATIVE CONDITIONS\n1A The General Terms of Approval from state authorities must b e complied with prior to, during,\nand at the completion of the development. The General Terms of Approval are:\na) Subsidence Advisory NSW, ref: TBA21-00305 & TBA21-02116, da ted 12 October 2021\nA copy of the General Terms of Approval are attached to this determination notice.\n(Inserted under MA2021/00192)\nWORKS NOT APPROVED\n1B Development consent has not been granted to the following e lements of the proposal (as\nmarked in red on the approved plans):\na) Streets tree planting within Darby Street, including associ ated tree planting enclosures\nand paving works; and\nb) Low height planting within the Darby Street footway for the extent of any Bus Zone\nSCHEDULE 3\nNote: Condition 3 requires low height planting within the Darb y Street footway for the\nfrontage of the development excluding the extent of the Bus Zone.\nWorks not approved are to be excluded from documentation submit ted for a Construction\nCertificate application.\n(Inserted under MA2021/00192)\nAPPROVED DOCUMENTATION","stage":"general","stage_basis":"heading","page":19},{"label":"2","code":null,"number":"2","title":"","text":"The development is to be implemented in accordance with the p lans and supporting\ndocuments set out in the following table except where modified b y a n y c o n d i t i o n s o f t h i s\nconsent.\nPlan No./Supporting\nDocument\nReference/\nVersion\nPrepared by Dated\nDA-A-000\nTitle Sheet & Locality\nPlan\nRev K Smith & Tzannes in association\nwith Clare Design\n02/11/2021\nDA-A-010\nSite Demolition Plan\nRev G Smith & Tzannes in association\nwith Clare Design\n11/10/2021\nDA-A-011\nDemolition Plan Level\n1& Mezzanine\nRev F Smith & Tzannes in association\nwith Clare Design\n11/10/2021\nDA-A-012\nOverall Site Plan\nRev I Smith & Tzannes in association\nwith Clare Design\n11/10/2021\nDA-A-032\nLandscape Plan -\nCover Sheet\nRev B Smith & Tzannes in association\nwith Clare Design\n15/10/2021\nDA-A-033\nLandscape Plan -\nExisting Site Plan\nRev B Smith & Tzannes in association\nwith Clare Design\n15/10/2021\nDA-A-034\nLandscape Plan - Site\nMasterplan\nRev B Smith & Tzannes in association\nwith Clare Design\n15/10/2021\nDA-A-035\nLandscape Plan -\nLaman Street\nElevation\nRev B Smith & Tzannes in association\nwith Clare Design\n15/10/2021\nDA-A-036\nLandscape Plan -\nDarby Street Elevation\nRev C Smith & Tzannes in association\nwith Clare Design\n15/10/2021\nDA-A-037\nLandscape Plan -\nPlan Details (1)\nRev B Smith & Tzannes in association\nwith Clare Design\n11/10/2021\nDA-A-038\nPlan Details (2)\nRev C Smith & Tzannes in association\nwith Clare Design\n15/10/2021\nDA-A-039\nLandscape Plan -\nProposed Planting\nSpecies\nRev B Smith & Tzannes in association\nwith Clare Design\n11/10/2021\nDA-A-100\nProposed Lower\nGround Floor Plan\nRev M Smith & Tzannes in association\nwith Clare Design\n02/11/2021\nDA-A-101\nProposed Ground\nFloor Plan\nRev N Smith & Tzannes in association\nwith Clare Design\n02/11/2021\nDA-A-102\nProposed First Floor\nPlan\nRev K Smith & Tzannes in association\nwith Clare Design\n02/11/2021\nDA-A-103\nProposed Roof Plan\nRev I Smith & Tzannes in association\nwith Clare Design\n11/10/2021\nDA-A-200\nElevations (North &\nEast)\nRev J Smith & Tzannes in association\nwith Clare Design\n02/11/2021\nDA-A-201\nElevations (South &\nWest)\nRev J Smith & Tzannes in association\nwith Clare Design\n02/11/2021\nDA-A-202\nSections\nRev H Smith & Tzannes in association\nwith Clare Design\n02/11/2021\nDA-A-903\nMaterials and Colours\nRev D Smith & Tzannes in association\nwith Clare Design\n29/10/2021\nDA-A-910\nPerspective\nRev A Smith & Tzannes in association\nwith Clare Design\n02/11/2021\nSTZ-0196-ID1 1of2\nSignage\nIssue v1 Smith & Tzannes in association\nwith Clare Design\n29/10/2013\nSTZ-0196-ID1 2of2\nSignage\nIssue v1 Smith & Tzannes in association\nwith Clare Design\n29/10/2013\nIn the event of any inconsistency between conditions of this de velopment consent and the\nplans/supporting documents referred to above, the conditions of this development consent\nprevail.\n(Amended under MA2021/00192)\nCONDITIONS TO BE SATISFIED PRIOR TO THE ISSUE OF A CONSTRUCTION CERTIFICATE\n2A. Additional details of the materials and finishes are to be submitted to the Development and\nBuilding Section of Council for approval prior to the issue of the Construction Certificate, and\nsuch details to be complied with and included in the details an d schedule(s) for the\nConstruction Certificate. Such details are to be consistent wi th the approved material and\ncolours (Drawing No. DA-A-903, prepared by Smith & Tzannes in a ssociation with Clare\nDesign, dated 29/10/2021) in type and quality.\n(Amended under MA2021/00192)","stage":"general","stage_basis":"heading","page":20},{"label":"3","code":null,"number":"3","title":"","text":"The Developer designing and constructing the following works in connection with the proposed\ndevelopment within the Darby Street and Queen Street public roa d reserve, adjacent to the\nsite, will provide at no cost to Council and in accordance with Council’s guidelines and design\nspecifications:\na) Footpath replacement to Council requirements\nb) Kerb and gutter replacement along Darby Street frontage\nc) New driveway crossing on Queen Street\nd) Associated drainage works\ne) Installation of low height planting such as shrubs, grasses, or ground covers to Council's\nrequirements within the Darby Street footway for the frontage o f the development site\nexcluding the extent of any Bus Zone. Each garden bed is to be 3m long and 600mm\nwide, offset 200mm from the Darby Street kerb. Spacing between garden beds is to be\n3m.\nf) The existing 3 metre long, 225mm size stormwater pipe downst ream of the existing kerb\ninlet pit at the corner of Laman and Darby Streets is to be upgraded to a 375mm pipe.\nEngineering and landscape design plans and specifications for t he works being undertaken\nwithin the public road reserve are required to be prepared by a suitably qualified practising civil\nengineer with experience and competence in the related field an d submitted to Council for\napproval pursuant to Section 138 of the Roads Act 1993 (NSW). T he consent must be\nobtained, or other satisfactory arrangements confirmed in writi ng from Council, before the\nissue of a Construction Certificate.\n(Amended under MA2021/00192)","stage":"general","stage_basis":"heading","page":21},{"label":"4","code":null,"number":"4","title":"","text":"The building is to be provided with adequate means of access for persons with disabilities in\norder to comply with the Building Code of Australia and the Disability Discrimination Act 1992.\nIn this regard, the applicant is to submit a design detail which has been certified by a qualified\nAccess Advisor* with the application for a Construction Certificate.\nNote:\ni) Compliance with the Building Code of Australia only can sti ll leave a building professional\nor building owner in contravention of the Disability Discrimination Act 1992.\nii) * A qualified Access Advisor is a current member of -\nAssociation of Consultants in Access Aust Inc\n326 Autumn Street, HERNE HILL, VIC. 3218.\nPh (03) 5221 2820\nwww.access.asn.au\niii) A qualified Access Advisor should carry current and relev ant public liability and public\nindemnity insurances for the practice of their trade.","stage":"general","stage_basis":"heading","page":22},{"label":"5","code":null,"number":"5","title":"","text":"All proposed loading bays and vehicular turning areas are to be constructed with a basecourse\nof adequate depth to suit design traffic, being sealed with eit her bitumen seal, asphaltic\nconcrete, concrete or interlocking pavers and being properly maintained. Full details are to be\nincluded in documentation for a Construction Certificate application.","stage":"general","stage_basis":"heading","page":22},{"label":"6","code":null,"number":"6","title":"","text":"Landscaping and any other obstructions to visibility are to b e kept clear of or limited in height\nto 1.2m in the 2 metre by 2.5 metre splay within the property b oundary each side of the\ndriveway entrance in accordance with AS/NZS 2890.1:2004 - Parking facilities - Off-street car\nparking. Full details are to be included in documentation for a Construction Certificate\napplication.","stage":"general","stage_basis":"heading","page":22},{"label":"7","code":null,"number":"7","title":"","text":"All stormwater runoff from the proposed development being man aged in accordance with the\nrequirements of the Section 7.06 ‘Stormwater’ of Newcastle Deve lopment Control Plan 2012\nand the associated Technical Manual and the latest issue of AS 3500.3 where applicable, as\nindicated on the stormwater management concept plan prepared by Arup (Job No. 278551,\nDrg. No. SK-H-001 (Drawings 1 to 7), dated 29.10.2021). Full de tails to be included in\ndocumentation for a Construction Certificate application.\n(Inserted under MA2021/00192)","stage":"general","stage_basis":"heading","page":22},{"label":"8","code":null,"number":"8","title":"","text":"All new impervious surfaces, including driveways and paved ar eas are to be drained to the\nnominated discharge controls, full details are to be included i n documentation for a\nConstruction Certificate application.","stage":"general","stage_basis":"heading","page":22},{"label":"9","code":null,"number":"9","title":"","text":"All existing trees on the site outside the envelope of the pr oposed building are to be preserved\nwhere practicable and all such trees being indicated on the required comprehensive landscape\ndesign plan and being adequately protected against damage durin g the building construction\nperiod. Full details are to be included in the documentation fo r a Construction Certificate\napplication.","stage":"general","stage_basis":"heading","page":22},{"label":"10","code":null,"number":"10","title":"","text":"The applicant is to comply with all requirements of the Hunt er Water Corporation regarding the\nconnection of water supply and sewerage services, including the payment of any required cash\ncontribution towards necessary amplification of service mains i n the locality as a result of the\nincreased intensity of land use proposed. A copy of the Corporation’s certificate of compliance\nis to be included in documentation for a Construction Certificate application.","stage":"general","stage_basis":"heading","page":22},{"label":"11","code":null,"number":"11","title":"","text":"Adequate facilities are to be provided in a screened locatio n within the premises for the storage\nof garbage, discarded or returnable packaging or other forms of trade wastes and\narrangements being made for regular removal and disposal of sam e. The required garbage\nfacility is to be suitable for the accommodation of Council app roved wheel type bins or bulk\nwaste containers. Full details are to be included in documentation for a Construction Certificate\napplication.","stage":"general","stage_basis":"heading","page":23},{"label":"12","code":null,"number":"12","title":"","text":"The premises are to be provided with adequate toilet facilit ies and wash hand basins for each\nsex in accordance with the provisions of the Building Code of A ustralia. Full details are to be\nincluded in the documentation for a Construction Certificate application.","stage":"general","stage_basis":"heading","page":23},{"label":"13","code":null,"number":"13","title":"","text":"The design and construction of the proposed development is t o be in accordance with the\nrelevant requirements of Australian Standard 4674:2004 - Design, Construction and Fit-Out of\nFood Premises. Full details are to be included in the documenta tion for the Construction\nCertificate application.","stage":"general","stage_basis":"heading","page":23},{"label":"14","code":null,"number":"14","title":"","text":"The proposed lighting of the premises is to be designed, pos itioned, and installed, including\nappropriate shielding and orientation of the lighting fixture, as to not give rise to obtrusive light,\ninterfere with traffic safety or detract from the amenity of surrounding properties in accordance\nwith Australian Standard 4282:1997 - Control of the obtrusive e ffects of outdoor lighting. Full\ndetails are to be included in the documentation for a Construction Certificate application.","stage":"general","stage_basis":"heading","page":23},{"label":"15","code":null,"number":"15","title":"(Deleted under MA2021/00192)","text":"","stage":"general","stage_basis":"heading","page":23},{"label":"16","code":null,"number":"16","title":"","text":"Prior to any ground disturbance works occurring on site, the applicant must obtain an approved\nSection 140 application under the Heritage Act 1977 to undertak e archaeological excavation\nof the study area. The applicant must comply with all the appro val conditions of the Section\n140 approval. Full details are to be included in documentation for a Construction Certificate\napplication.\n(Amended under MA2021/00192)","stage":"general","stage_basis":"heading","page":23},{"label":"17","code":null,"number":"17","title":"","text":"Prior to the work commencing and before the release of the C onstruction Certificate an archival\nrecord of the building, both internally and externally is to be made that is consistent with the\nNSW Heritage Office publications:\na) How to Prepare Archival Records of Heritage Items (1998); a nd\nb) Photographic Recording of Heritage Items using Film or Digi tal Capture (2006).\nThe archival record is to be submitted to Council for inclusion in the City Library collection prior\nto the issue of the Construction Certificate. Confirmation that the records have been submitted\nto Council shall be provided to the Principal Certifying Author ity prior to the issue of a\nConstruction Certificate.\n(Amended under MA2021/00192)","stage":"general","stage_basis":"heading","page":23},{"label":"18","code":null,"number":"18","title":"","text":"The building floor level of the plant room, main switch boar d room and communications area\nbeing set a minimum of 300mm above the local 1 in 100 year ARI flood level. Details to be\nindicated on plans for a Construction Certificate application.\n(Amended under MA2021/00192)\n18A The proposed awning is to be designed in a manner that is consistent with Element 7.10 ‘Street\nAwnings and Balconies’ of the Newcastle Development Control Pla n 2012. Full details are to\nbe included in documentation for a Construction Certificate application.\n(Inserted under DA2010/1278.02 - 3 September 2012)\n18B The existing 3 metre long, 225mm size stormwater pipe downs tream of the existing kerb inlet\npit at the corner of Laman and Darby Streets is to be upgraded to a 375mm pipe.\nA separate application must be lodged and consent obtained fro m Council for all works within\nthe road reserve pursuant to Section 138 of the Roads Act 1993 (NSW). The consent must be\nobtained, or other satisfactory arrangements confirmed in writi ng from Council, before the\nissue of a Construction Certificate.\n(Inserted under MA2021/00192)\n18C The stormwater design is to ensure post-development stormwa ter flows do not exceed pre-\ndevelopment flows to both Queen Street and Darby Street in acco rdance with Element 7.06\n‘Stormwater’ of Newcastle Development Control Plan 2012. Full d etails are to be provided as\npart of a construction certificate application.\n(Inserted under MA2021/00192)\n18D The applicant is required to engage an electrical consultan t or contractor to complete an online\napplication to Ausgrid for the connection of the approved devel opment to the adjacent\nelectricity network infrastructure.\n(Inserted under MA2021/00192)\n18E Provision is to be made on the site for the installation of a ‘kiosk’ type electricity substation\nshould such be required by the electricity authority and any such ‘kiosk’ being located in public\nreserves and/or private land and are not to be located within r oad reserves. Any such\nsubstation is to be appropriately screened to ensure the visual amenity of the streetscape is\nmaintained. Full details are to be included in documentation fo r a Construction Certificate\napplication.\n(Inserted under MA2021/00192)\n18F A title search of the development site should be completed to check for existing electricity\neasements. If easements are present, Ausgrid must assess the pr oposed activity within the\neasement. Reference should be given to Ausgrid's “Living with E lectricity Easements”\nbrochure. Full details are to be included in documentation for a Construction Certificate\napplication.\n(Inserted under MA2021/00192)\n18G The internal floor level of the 'Lower Ground Floor' is not to be any lower than RL 7.4 AHD as\nindicated in the approved plans. Basement or similar structures below this level will require a\nseparate application to Council. Full details are to be include d in documentation for a\nConstruction Certificate application.\n(Inserted under MA2021/00192)\nCONDITIONS TO BE SATISFIED PRIOR TO THE COMMENCEMENT OF WORK AN D DURING\nTHE CONSTRUCTION PHASE","stage":"general","stage_basis":"heading","page":23},{"label":"19","code":null,"number":"19","title":"","text":"A Registered Surveyor's certificate detailing the setting ou t of the proposed building on the\nsite, including the relationship of the set out building to property boundaries, is to be submitted\nto the Principal Certifying Authority before construction is commenced.","stage":"general","stage_basis":"heading","page":24},{"label":"20","code":null,"number":"20","title":"","text":"A commercial type vehicular crossing up to 13.5m with approp riate splays being constructed\nacross the public footway at the proposed driveway entrance/exi t at no cost to Council and in\naccordance with Crossing Standard Details A1300.\n(Amended under MA2021/00192)","stage":"general","stage_basis":"heading","page":24},{"label":"21","code":null,"number":"21","title":"","text":"Any proposed work within the public road reserve, including driveway works, reinstatement of\na kerb or installation of drainage, is to be the subject of the separate approval of Council prior\nto commencement.\nNote: A separate approval from Council must be obtained for al l works within the public road\nreserve pursuant to Section 138 of the Roads Act 1993 (NSW). For further information\ncontact Council’s Works Depot on 4974 6000 to request a Road Op ening Approval. A\nfee will be payable in this regard.\n21A Any structure on or over the public road reserve, including balconies and awnings, is to be the\nsubject of a separate consent from Council, under Section 138 of the Roads Act 1993, prior to\ncommencement of work.\nNote: A separate approval from Council must be obtained for al l structures within the public\nroad reserve pursuant to Section 138 of the Roads Act 1993. For further information\ncontact Council’s Strategic Property and Fleet Management Services on 4974 2000 to\nrequest a Road Consent. A fee will be payable in this regard.\n(Inserted under DA2010/1278.02 - 3 September 2012)\n21B Prior to the commencement of any works within the public ro ad reserve, details shall be\nsubmitted with the Roads Act Application for the proposed awning, demonstrating compliance\nwith the following:\na) Appropriate lighting being provided for the carpark and ped estrian pathways in\naccordance with AS 1158 - Lighting and AS 4282 - Control of the Obtrusive Effects of\nOutdoor Lighting.\nb) The design of the awning is to include cutout segments (if needed) to accommodate\nstreet trees.\n(Inserted under DA2010/1278.02 - 3 September 2012)","stage":"general","stage_basis":"heading","page":24},{"label":"22","code":null,"number":"22","title":"","text":"Prior to commencement of site works the developer submitting to Council for approval a\nConstruction Traffic Management Plan addressing traffic control measures to be utilised in the\npublic road reserve during the construction phase.\nNote: The required plan is to ensure the provision for safe, c ontinuous movement of traffic\nand pedestrians within the road reserve. The plan is to be prepared in accordance with\nAustralian Standard 1742.3 - 2002.","stage":"before_work","stage_basis":"text-under-general-heading","page":25},{"label":"23","code":null,"number":"23","title":"","text":"Prior to the commencement of any works in the public road re serve, the developer providing\nwritten notification to the adjoining landowners of the intenti on to start works, advising details\nof the scheduling of works and nominating a contact person. A l egible prominent sign stating\nthe name of the developer and contractor and a 24 hour contact telephone number is to also\nbe displayed on-site during the construction period.","stage":"before_work","stage_basis":"text-under-general-heading","page":25},{"label":"24","code":null,"number":"24","title":"","text":"Toilet facilities are to be available or provided at the wor k site before works begin and be\nmaintained until the works are completed, at a ratio of one toi let plus one additional toilet for\nevery 20 persons employed at the site. Each toilet is to:\na) be a standard flushing toilet connected to a public sewer, or\nb) have an on-site effluent disposal system approved under the Local Government Act 1993\n(NSW), or\nc) be a temporary chemical closet approved under the Local Government Act 1993 (NSW).","stage":"general","stage_basis":"heading","page":25},{"label":"25","code":null,"number":"25","title":"","text":"A Hazardous Substances Management Plan is to be prepared by a competent person for the\nbuilding(s) or parts of the building(s) proposed to be demolished in accordance with Australian\nStandard 2601:2001 - The Demolition of Structures. A copy of th e Hazardous Substances\nManagement Plan is to be provided to Council (marked to Attenti on: Compliance Services)\nand the demolisher prior to commencement of work.","stage":"general","stage_basis":"heading","page":25},{"label":"26","code":null,"number":"26","title":"","text":"Any demolition works are to be undertaken in accordance with Australian Standard 2601:2001\n- The Demolition of Structures and the following requirements:\na) Demolition works shall be conducted in accordance with the submitted Hazardous\nSubstances Management Plan and a copy of the Hazardous Substanc es Management\nPlan shall be kept on-site for the duration of the proposed development;\nb) The removal, handling and disposal of any asbestos material is to be undertaken only\nby an asbestos removal contractor who holds the appropriate class of Asbestos Licence,\nissued by the WorkCover Authority of NSW;\nc) A copy of all waste disposal receipts are to be kept on-sit e for the duration of the\nproposed development and made available to authorised Council Officers upon request;\nd) Seven working days notice in writing is to be given to Coun cil and the owners/occupiers\nof neighbouring premises prior to the commencement of any demol ition works. Such\nwritten notice is to include the date demolition will commence and details of the name,\naddress, contact telephone number(s) and licence details (type of licences held and\nlicence numbers) of any asbestos removal contractor and demolit ion contractor.\nNotification to owners/occupiers of neighbouring premises shall also include Council’s\ncontact telephone number (49742000) and the Workcover Authority of NSW telephone\nnumber (49212900);\ne) On sites where asbestos materials are to be removed, a stan dard commercially\nmanufactured sign containing th e words ‘DANGER ASBESTOS REMOVAL I N\nPROGRESS’ measuring not less than 400mm x 300mm is to be erecte d in a prominent\nposition during asbestos removal works.","stage":"general","stage_basis":"heading","page":26},{"label":"27","code":null,"number":"27","title":"","text":"The demolisher is to ensure that all services (ie water, tel ecommunications, gas, electricity,\nsewerage etc), are disconnected in accordance with the relevant authority’s requirements prior\nto demolition.","stage":"general","stage_basis":"heading","page":26},{"label":"28","code":null,"number":"28","title":"","text":"Any demolition/waste building materials that are not suitabl e for recycling are to be disposed\nof at Council’s Summerhill Waste Management Facility or other approved site.","stage":"general","stage_basis":"heading","page":26},{"label":"29","code":null,"number":"29","title":"","text":"At a minimum, the following waste management measures shall be implemented during the\nconstruction phase:\na) A waste container of at least one cubic metre capacity shal l be provided, maintained and\nregularly serviced from the commencement of operations until th e completion of the\nbuilding for the reception and storage of waste generated by th e construction of the\nbuilding and associated waste.\nb) The waste container is to be, at minimum, constructed with a 'star' picket (corners) and\nweed control mat (sides), or equivalent. The matting is to be securely tied to the pickets.\nc) Appropriate provision is to be made to prevent wind blown r ubbish leaving the site.\nd) Footpaths, road reserves and public reserves are to be main tained clear of rubbish,\nbuilding materials and all other items.\nNote: Fines may be issued for pollution/littering offences und er the Protection of the\nEnvironment Operations Act 1997 (NSW).","stage":"general","stage_basis":"heading","page":26},{"label":"30","code":null,"number":"30","title":"","text":"If construction / demolition work is likely to cause pedestr ian or vehicular traffic in a public place\nto be obstructed or rendered inconvenient, or involves the need\nto enclose a public place, a\nhoarding or fence must be erected between the work site and the public place. If necessary,\nan awning is to be erected, sufficient to prevent any substance from, or in connection with, the\nwork falling into the public place. Any such hoarding, fence or awning is to be removed when\nthe work has been completed.\nAn application is to be made to and approved by Council for the erection of a hoarding or part\nclosure of the footway prior to construction being commenced. S uch overhead structure or\nprotective fence shall comply with the Occupational Health and Safety Act 2000 ( N S W ) ,\nOccupational Health and Safety Regulation 2001 (NSW) and any relevant approved industry\ncode of practice. Notice of intention of commencement must be given to WorkCover New South\nWales.","stage":"general","stage_basis":"heading","page":26},{"label":"31","code":null,"number":"31","title":"","text":"The work site must be kept lit between sunset and sunrise if it is likely to be hazardous to\npersons in the public place.","stage":"general","stage_basis":"heading","page":27},{"label":"32","code":null,"number":"32","title":"","text":"A sign must be erected in a prominent position on any site o n which building work, subdivision\nwork or demolition work is being carried out:\na) showing the name, address and telephone number of the princ ipal certifying authority for\nthe work, and\nb) showing the name of the principal contractor (if any) for a ny building work and a\ntelephone number on which that person may be contacted outside working hours, and\nc) stating that unauthorised entry to the work site is prohibi ted. Any such sign is to be\nmaintained while the building work, subdivision work or demolition work is being carried\nout, but must be removed when the work has been completed.","stage":"general","stage_basis":"heading","page":27},{"label":"33","code":null,"number":"33","title":"","text":"All building work must be carried out in accordance with the provisions of the Building Code of\nAustralia.","stage":"general","stage_basis":"heading","page":27},{"label":"34","code":null,"number":"34","title":"","text":"All excavations and backfilling are to be executed safely in accordance with appropriate\nprofessional standards and excavations are to be properly guard ed and protected to prevent\nthem from being dangerous to life and property.","stage":"general","stage_basis":"heading","page":27},{"label":"35","code":null,"number":"35","title":"","text":"If the development involves an excavation that extends below the level of the base of the\nfootings of a building on adjoining land, the person having the benefit of the development\nconsent must, at the person’s own expense:\na) protect and support the adjoining premises from possible da mage from the excavation,\nand\nb) where necessary, underpin the adjoining premises to prevent any such damage.\nThe above requirements does not apply if the person having the benefit of the development\nconsent owns the adjoining land or the owner of the adjoining land has given consent in writing\nto the requirements not applying.","stage":"general","stage_basis":"heading","page":27},{"label":"36","code":null,"number":"36","title":"","text":"The proposed remediation woks being carried out in accordanc e with the requirements of the\nsubmitted Remedial Action Plan (RAP) prepared by Douglas Partners Pty Ltd (February 2012),\nthe requirements and the conditions of this consent.","stage":"general","stage_basis":"heading","page":27},{"label":"37","code":null,"number":"37","title":"","text":"A copy of the ongoing environmental management plan is to be kept on the premises at all\ntimes and implemented as required in relation to site maintenan ce and future works involving\nexcavation.","stage":"general","stage_basis":"heading","page":27},{"label":"38","code":null,"number":"38","title":"","text":"Remediation works being carried out in accordance with the r equirements of Element 4.2\n(Contaminated Land Management) and associated technical manual.","stage":"general","stage_basis":"heading","page":27},{"label":"39","code":null,"number":"39","title":"","text":"Any excavated material to be removed from the site is to be assessed, classified, transported\nand disposed of in accordance with the Department of Environmen t and Climate Change’s\n(DECC) ‘Waste Classification Guidelines Part 1: Classifying Waste’.","stage":"general","stage_basis":"heading","page":27},{"label":"40","code":null,"number":"40","title":"","text":"Any fill material imported into the site is to be Virgin Exc avated Natural Material or material\nsubject to a Resource Recovery Exemption that is permitted to b e used as a fill material, in\naccordance with the provisions of the Protection of the Environment Operations Act 1997 and\nthe Protection of the Environment (Waste) Regulation 2005.","stage":"general","stage_basis":"heading","page":28},{"label":"41","code":null,"number":"41","title":"","text":"Any fill material subject to a Resource Recovery Exemption r eceived at the site must be\naccompanied by documentation demonstrating that material’s comp liance with the conditions\nof the exemption, and this documentation must be provided to Council officers or the Principal\nCertifying Authority on request.","stage":"general","stage_basis":"heading","page":28},{"label":"42","code":null,"number":"42","title":"","text":"All building materials, plant and equipment is to be placed on the site of the development so\nas to ensure that pedestrian and vehicular access in public pla ces is not restricted and to\nprevent damage to the road reserve. The storage of building ma terials on Council reserves\nincluding the road reserve is not permitted.","stage":"general","stage_basis":"heading","page":28},{"label":"43","code":null,"number":"43","title":"","text":"Any alteration to natural surface levels on the site is to b e undertaken in such a manner as to\nensure that there is no increase in surface water runoff to adjoining properties or that runoff is\nimpounded on adjoining properties, as a result of the development.","stage":"general","stage_basis":"heading","page":28},{"label":"44","code":null,"number":"44","title":"","text":"All loading bays are to be permanently marked out on the pav ement surface, being clearly\nindicated by signs.","stage":"general","stage_basis":"heading","page":28},{"label":"45","code":null,"number":"45","title":"","text":"The vehicular entrance and exit driveways and the direction of traffic movement within the site\nare to be clearly indicated by means of reflectorised signs and pavement markings.","stage":"general","stage_basis":"heading","page":28},{"label":"46","code":null,"number":"46","title":"","text":"Construction/demolition work that generates noise that is au dible at residential premises is to\nbe restricted to the following times:\n Monday to Friday, 7:00 am to 6:00 pm;\n Saturday, 8:00 am to 1:00 pm;\nNo noise from construction/demolition work is to be generated on Sundays or Public Holidays.","stage":"general","stage_basis":"heading","page":28},{"label":"47","code":null,"number":"47","title":"","text":"Council’s ‘PREVENT POLLUTION’ sign is to be erected and main tained in a conspicuous\nlocation on or adjacent to the property boundary so it is clear ly visible to the public or at other\nlocations on the site as otherwise directed by Council for the duration of demolition and\nconstruction work.\nNote: Council’s ‘PREVENT POLLUTION’ sign can be obtained by pr esenting your\ndevelopment application receipt at Council’s Customer Enquiry C ounter at 282 King\nStreet Newcastle.","stage":"general","stage_basis":"heading","page":28},{"label":"48","code":null,"number":"48","title":"","text":"Erosion and sediment control measures are to be implemented prior to the commencement of\nworks and be maintained during the period of construction in ac cordance with the details set\nout on the Erosion and Sediment Control Plan submitted with the application, and with the\nbelow requirements:\na) Control over discharge of stormwater and containment of run -off and pollutants leaving\nthe site must be undertaken through the installation of erosion control devices such as\ncatch drains, energy dissipaters, level spreaders and sediment control devices such as\nhay bale barriers, filter fences, filter dams and sediment basins.\nb) Controls are not to be removed until the site is stable wit h all bare areas supporting an\nestablished vegetative cover. Erosion and sediment control measures are to be designed\nin accordance with the requirements of the Managing Urban Storm water: Soils and\nConstruction 4th Edition - Vol. 1 (the ‘Blue Book’) published by Landcom, 2004.","stage":"general","stage_basis":"heading","page":28},{"label":"49","code":null,"number":"49","title":"","text":"Prior to the commencement of work, a 3m wide all weather veh icle access is to be provided\nfrom the kerb and gutter to the building under construction, to reduce the potential for soil\nerosion. Sand shall not be stockpiled on the all weather vehicle access.","stage":"before_work","stage_basis":"text-under-general-heading","page":29},{"label":"50","code":null,"number":"50","title":"","text":"A temporary protective crossing is to be provided over the f ootway for vehicular traffic before\ndemolition or building operations are commenced. This approval does not permit access to the\nproperty over any adjacent private or public land.","stage":"general","stage_basis":"heading","page":29},{"label":"51","code":null,"number":"51","title":"","text":"All necessary measures are to be undertaken to control dust pollution from the site. These\nmeasures must include, but not are limited to:\na) restricting topsoil removal;\nb) regularly and lightly watering dust prone areas (note: prev ent excess watering as it can\ncause damage and erosion;\nc) alter or cease construction work during periods of high win d;\nd) erect green or black shadecloth mesh or similar products 1. 8m high around the perimeter\nof the site and around every level of the building under construction.","stage":"general","stage_basis":"heading","page":29},{"label":"52","code":null,"number":"52","title":"","text":"Where the proposed development involves the destruction or d isturbance of any existing\nsurvey monuments, those monuments affected are to be relocated at no cost to Council by a\nSurveyor registered under the Surveying and Spatial Information Act 2002 (NSW).","stage":"general","stage_basis":"heading","page":29},{"label":"53","code":null,"number":"53","title":"","text":"All external items of air conditioning plant are to be scree ned or positioned in such a manner\nas to not detract from the visual presentation of the building.\n53A There are existing overhead electricity network assets in Q ueen and Darby Street, adjacent to\nthe development site. Workcover Code of Practice 2006 Work Near Overhead Powerlines\noutlines the minimum safety separation requirements between these mains/poles to structures\nwithin the development throughout the construction phase. Any r elocation of overhead mains\nrequired to maintain minimum safety clearances is at the cost of the person having the benefit\nof this consent.\n(Inserted under MA2021/00192)\n53B The development is in proximity to underground electricity assets. In addition to DBYD\nsearches a ground search is to be conducted to locate electrici ty assets immediately prior to\ncommencing work to check for updates of installed utilities. Du ring construction work is to be\nundertaken in accordance with Ausgrid’s Network Standard 156 - Working near or around\nunderground cables. Any alterations to Ausgrid’s underground el ectricity main will be\ncontestable works and funded by the person having the benefit of this consent.\n(Inserted under MA2021/00192)\n53C Prior to works commencing, all contractors and sub-contract ors are to undergo a site induction\nprovided by a suitably qualified heritage professional, which i s to include the significance of\nthe site and the relevant obligations under the Heritage Act 1977 and the National Parks and\nWildlife Act 1974.\n(Inserted under MA2021/00192)\n53D The development is to be undertaken in accordance with the recommendations in the Historical\nArchaeological Assessment and Statement of Heritage Impact prep ared by Austral\nArchaeology (dated 4 November 2021).\n(Inserted under MA2021/00192)\n53E If unanticipated suspected Aboriginal heritage items are un covered at any time throughout the\nlife of the project, excavation or disturbance of the area is t o stop immediately and Heritage\nNSW is to be notified in accordance with Section 89A of the National Parks and Wildlife Act\n1974 (NPW Act). Aboriginal objects in NSW are protected under the N\nPW Act. Unless the\nobjects are subject to a valid Aboriginal Heritage Impact Permi t, work must not recommence\nuntil approval to do so has been provided by Heritage NSW.\n(Inserted under MA2021/00192)\n53F Construction works are to be carried out in accordance with the recommendations of;\na) Report: Douglas Partners Pty Ltd (February 2021) Report on G roundwater Sampling\nR.001.Rev0; and\nb) Letter: Douglas Partners Pty Ltd (8 November 2021) Proposed Rainwater Tank.\nR.001.Rev0.\n(Inserted under MA2021/00192)\n53G Monitoring for volatile gases shall be conducted by a suita bly qualified and experienced\nenvironmental consultant during the excavations for the rainwat er tank. If volatile gases are\ndetected which exceed appropriate guidelines, works are to imme diately cease and advice is\nto be sought from the environmental consultant and recommendati ons in respect to the\nmanagement of health or environmental risk are to be implemente d in accordance with\nappropriate guidelines and legislation.\n(Inserted under MA2021/00192)\nCONDITIONS TO BE SATISFIED PRIOR TO THE ISSUE OF AN OCCUPATION CERTIFICATE,\nA SUBDIVISION CERTIFICATE OR A STRATA CERTIFICATE","stage":"general","stage_basis":"heading","page":29},{"label":"54","code":null,"number":"54","title":"","text":"Street lighting being upgraded at the cost of the developer to Standard P3 in accordance with\nAS 1158.1.1 - Road Lighting on Darby Street across the frontage of the site. The lighting\nupgrade works being completed prior to the occupation of the portion of the premise the subject\nof this application.\nNote: The developer is to liaise with Energy Australia in relation to the design and construction\nof the street lighting.","stage":"general","stage_basis":"heading","page":30},{"label":"55","code":null,"number":"55","title":"","text":"Following implementation of the RAP and prior to occupation of the land, a validation report\nand ongoing environmental management plan is to be prepared by a suitably qualified\nconsultant in accordance with relevant NSW State Government Guidelines and provided to the\nPrincipal Certifier and Council.","stage":"general","stage_basis":"heading","page":30},{"label":"56","code":null,"number":"56","title":"","text":"Prior to selection and location of mechanical plant, (includ ing air conditioning, refrigeration and\nventilation systems), noise emission data for the equipment is to be reviewed by an\nappropriately qualified acoustic consultant. Written certificat ion by the acoustic consultant\nregarding the appropriateness of the equipment and installation location is to be provided to\nthe Principal Certifier and Council prior to the issue of any O ccupation Certificate for the\npremises.","stage":"general","stage_basis":"heading","page":30},{"label":"57","code":null,"number":"57","title":"","text":"All public footways, footpaving, kerbs, gutters and road pav ement damaged during the works\nare to be immediately repaired following the damage, to a satis factory state that provides for\nsafe use by pedestrians and vehicles. Full restoration of the d amage is to be carried out to\nCouncil’s satisfaction prior to the completion of demolition wo rk or prior to the issue of any\noccupation certificate in respect of development involving building work.","stage":"general","stage_basis":"heading","page":30},{"label":"58","code":null,"number":"58","title":"","text":"Any redundant existing vehicular crossing is to be removed a t no cost to Council and the public\nfootway and kerb being restored to match the existing infrastructure and be completed prior to\nthe issuing of any Occupation Certificate for the proposed development.\nNote: A separate approval from Council must be obtained for al l works within the public road\nreserve pursuant to Section 138 of the Roads Act 1993 (NSW). For further information\ncontact Council’s Works Depot on 4974 6000 to request a Road Op ening Approval. A\nfee will be payable in this regard.","stage":"general","stage_basis":"heading","page":30},{"label":"59","code":null,"number":"59","title":"","text":"The whole of the land to which the art gallery relates is to be consolidated into a single title\nand documentary evidence of the lodgement for registration of a survey plan of consolidation\nwith NSW Government Land & Property Information being submitted to Council prior to the\nissuing of an Occupation Certificate for the proposed development.","stage":"general","stage_basis":"heading","page":31},{"label":"60","code":null,"number":"60","title":"","text":"A copy of the stormwater drainage design plans approved with the Construction Certificate\nwith \"work as executed\" levels indicated, shall be submitted to Newcastle City Council prior to\noccupation of the building. The plans shall be prepared by a Practicing Professional Engineer\nor Registered Surveyor experienced in the design of stormwater drainage systems.","stage":"general","stage_basis":"heading","page":31},{"label":"61","code":null,"number":"61","title":"","text":"A Landscape Practical Completion Report is to be submitted t o the Principal Certifying\nAuthority prior to the issue of the Final Occupation Certificat e. The report is to verify that all\nlandscape works have been carried out in accordance with the co mprehensive landscape\ndesign plan and specifications that were required to be include d in documentation for a\nConstruction Certificate application and is to verify that an effective maintenance program has\nbeen commenced.","stage":"general","stage_basis":"heading","page":31},{"label":"62","code":null,"number":"62","title":"","text":"The Landscape Architect is to submit a Certificate of Practi cal Completion to the Principal\nCertifying Authority which verifies that the street tree planti ng works have been undertaken in\naccordance with the planting detail provided and to a professional standard. Refer to Council’s\nstandard Practical Completion Report form. Council’s Landscape Project Officer may be\ncontacted on Ph: (02) 4974 2675 to inspect the works at any stage.","stage":"general","stage_basis":"heading","page":31},{"label":"63","code":null,"number":"63","title":"","text":"A Landscape Establishment Report is to be submitted to Newcastle City Council at 52 weeks\nafter the date of Practical Completion. This report shall state the actual maintenance carried\nout on site, including maintenance records such as site work report sheets, diary entries or log\nbooks which show frequency of watering, weeding, mulching, pers onnel and any other\nremediation or rectification works carried out.","stage":"general","stage_basis":"heading","page":31},{"label":"64","code":null,"number":"64","title":"","text":"The applicant preparing and implementing a Traffic Managemen t Plan for the operation of the\nQueen Street loading dock to control vehicle and pedestrian activity during service operations,\nsuch being operational prior to the issue of an Occupation Certificate for the premises.","stage":"general","stage_basis":"heading","page":31},{"label":"65","code":null,"number":"65","title":"","text":"The developer being responsible for the provision of additio nal regulatory signage in Darby\nand Queen Streets adjacent to the site frontage and all adjustm ents to and/or relocation of\nexisting regulatory signage necessary as part of this developme nt, at no cost to Council and\nin accordance with Council requirements, such works being imple mented prior to the\noccupation of the portion of the premise the subject of this application.\nNote: The provision of additional regulatory signage and alter ations to existing regulatory\nsignage will need to be referred to the Newcastle City Traffic Committee for approval\nprior to installation.","stage":"general","stage_basis":"heading","page":31},{"label":"66","code":null,"number":"66","title":"","text":"The building floor level of the plant room, main switch boar d room and communications area\nbeing set a minimum of 300mm above the local 1 in 100 year ARI flood level. The finished\nfloor levels are to be certified by a registered Surveyor prior to the placement of the floor\nmaterial and a copy of the Surveyor’s Certificate is to be forw arded to the Principal Certifying\nAuthority.\n(Amended under MA2021/00192)","stage":"general","stage_basis":"heading","page":31},{"label":"67","code":null,"number":"67","title":"","text":"Prior to issue of an Occupation Certificate, any food busine ss must notify the relevant\nenforcement agencies, under the Food Act 2003 (NSW) and (for licensed food businesses)\nunder the Food Regulation 2010 (NSW). Notification is to be provided to Council and the NSW\nFood Authority.\nNote: To arrange notification of the food business with Council go to www.newcastle.gov.au\nand download a copy of the ‘Council Food Business Notification Form’ or contact\nCouncil’s Environmental Health Services on (02) 4974 2525. To notify with the NSW\nFood Authority go to www.foodnotify.nsw.gov.au and follow the instructions.\n67A 17 suitable replacement trees either on/adjoining the subj ect site, or off site within a distance\nof 400 meters as measured from any point along the development site boundary, are required\nin order to replace the trees being removed as part of the development. All replacement trees\nare to be planted prior to the issue of an Occupation Certifica te, and a list provided to the\ncertifying authority.\n(Amended under MA2021/00192)\n67B The awning on the Darby Street, Queen Street and Laman Stre et frontages is required to be\nconstructed prior to the issue of the Occupation Certificate fo r the development the subject of\nthis consent.\n(Amended under DA2010/1278.02 - 3 September 2012)\n67C (Deleted under MA2021/00192)\n67D Prior to the release of the Occupation Certificate, the Applicant must demonstrate to the written\nsatisfaction of Council, that they have satisfied the requireme nts for lodging all final\narchaeological excavation reports required under any and all s. 140 applications under the\nHeritage Act 1977 which have been approved by the Heritage Council of NSW for this site.\n(Inserted under MA2021/00192)\nCONDITIONS TO BE SATISFIED DURING THE OPERATION AND USE THE DEVELOPMENT","stage":"before_oc","stage_basis":"text-under-general-heading","page":31},{"label":"68","code":null,"number":"68","title":"(Deleted under MA2021/00192)","text":"","stage":"general","stage_basis":"heading","page":32},{"label":"69","code":null,"number":"69","title":"","text":"The maximum number of patrons permitted within the café and associated terrace area is to\nbe restricted to 100 persons in total. A sign must be displayed in a prominent posit ion in the\ncafe stating the maximum number of patrons, as specified in the development consent, that\nare permitted in the café.\n(Amended under MA2021/00192)","stage":"general","stage_basis":"heading","page":32},{"label":"70","code":null,"number":"70","title":"","text":"The hours of operation or trading of the premises are to be not more than from:\nDAY START FINISH\nMonday 6am 10pm Same day\nTuesday 6am 10pm Same day\nWednesday 6am 10pm Same day\nThursday 6am 10pm Same day\nFriday 6am 10pm Same day\nSaturday 6am 10pm Same day\nSunday 6am 10pm Same day\nunless a separate application to vary the hours of operation or trading has been submitted to\nand approved by Council.\n(Amended under MA2021/00192)","stage":"general","stage_basis":"heading","page":32},{"label":"71","code":null,"number":"71","title":"(Deleted under MA2021/00192)","text":"","stage":"general","stage_basis":"heading","page":32},{"label":"72","code":null,"number":"72","title":"","text":"The use and occupation of the premises, including all plant and equipment installed thereon,\nis not to give rise to any offensive noise, as defined under th e Protection of the Environment\nOperations Act 1997 (NSW).\nShould Council consider offensive noise has emanated from the premises, the owner/occupier\nof the premises will be required to submit an acoustic assessme nt prepared by a suitably\nqualified acoustical consultant recommending appropriate acoust ic measures necessary to\nensure future compliance with this condition and will be required to implement such measures\nwithin a nominated period. Furthermore, written certification f rom the said consultant\nconfirming the recommended acoustic measures have been satisfactorily implemented will be\nrequired to be submitted to Council prior to the expiration of the nominated period.","stage":"general","stage_basis":"heading","page":32},{"label":"73","code":null,"number":"73","title":"","text":"The use and occupation of the premises is not to give rise t o the emission of any ‘air impurity’\nas defined under the Protection of the Environment Operations Act 1997 (NSW), that interferes\nunreasonably with the amenity of neighbouring premises and/or other sensitive receivers.\nShould Council consider that unreasonable levels of air impurities have been emitted from the\npremises, the owner/occupier will be required to engage a suita bly qualified consultant to\nrecommend measures to control emissions of air impurities to an acceptable level and such\nmeasures being implemented within a nominated time period. Furthermore, written certification\nfrom the suitably qualified consultant will be required to be submitted to Council confirming that\nair impurity emissions from the premises do not interfere unrea sonably with the amenity of\nneighbouring premises and/or other sensitive receptors before the expiration of the nominated\nperiod.","stage":"general","stage_basis":"heading","page":33},{"label":"74","code":null,"number":"74","title":"(Deleted under MA2021/00192)","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"75","code":null,"number":"75","title":"(Deleted under MA2021/00192)","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"76","code":null,"number":"76","title":"(Deleted under MA2021/00192)","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"77","code":null,"number":"77","title":"(Deleted under MA2021/00192)","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"78","code":null,"number":"78","title":"(Deleted under MA2021/00192)","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"79","code":null,"number":"79","title":"(Deleted under MA2021/00192)","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"80","code":null,"number":"80","title":"","text":"No flashing, chasing or scintillating lighting or promotiona l material of a visually intrusive nature\nis to be installed or displayed on the exterior of the premises.","stage":"general","stage_basis":"heading","page":33},{"label":"81","code":null,"number":"81","title":"","text":"Any flags, bunting or other promotional material of a like n ature are to be arranged and properly\nmaintained in a manner which does not detract from the appearan ce of the premises or the\nstreetscape and which does not represent a hazard to the public.","stage":"general","stage_basis":"heading","page":33},{"label":"82","code":null,"number":"82","title":"","text":"The driveway crossing, loading areas and stormwater manageme nt system are to be properly\nmaintained for the life of the development.","stage":"general","stage_basis":"heading","page":33},{"label":"83","code":null,"number":"83","title":"","text":"Vehicles are to be loaded or unloaded standing wholly within the premises and within loading\nbays designated on the submitted plans or as otherwise provided in accordance with the\nconditions of this consent and under no circumstances are vehic les to be loaded or unloaded\nat the kerbside, across the public footpath or in a manner which obstructs vehicular access to\nthe site.","stage":"general","stage_basis":"heading","page":33},{"label":"84","code":null,"number":"84","title":"","text":"Proposed driveways and turning areas are to be maintained cl ear of obstruction and be used\nexclusively for purposes of loading and unloading, and vehicle access, respectively. Under no\ncircumstances are such areas to be used for the storage of goods or waste materials.","stage":"general","stage_basis":"heading","page":33},{"label":"85","code":null,"number":"85","title":"","text":"The maximum size vehicle that shall access the Queen Street loading dock is to be a heavy\nrigid vehicle (HRV) id vehicle (MRV) as defined in AS 2890.2. Under no circumstances should\nan articulated vehicle enter the site.","stage":"general","stage_basis":"heading","page":33},{"label":"86","code":null,"number":"86","title":"","text":"Any liquid wastes from the premises, other than stormwater a re to be either discharged to the\nsewers of the Hunter Water Corporation in accordance with an ap proved Trade Waste\nAgreement or collected and disposed of by a licensed waste transport contractor in accordance\nwith the Department of Environment and Climate Change ‘Waste Classification Guidelines Part\n1: Classifying Waste’.\n86A Provision is to be made for regular maintenance to ensure t he continuing structural integrity\nand attractive appearance of the street awning. A maintenance p lan is to be developed and\ninclude:\na) annual inspection of structural components\nb) repainting, as required\nc) regular maintenance to guttering and downpipes\nd) regular cleaning and replacement of defective lighting, adv ertising or other deteriorated\ncomponents of the awning\ne) regular cleaning of awning glazing, where installed.\n(Inserted under DA2010/1278.02 - 3 September 2012)\nADVISORY MATTERS","stage":"general","stage_basis":"heading","page":33},{"label":"87","code":null,"number":"87","title":"","text":"It is recommended that, prior to commencement of work, the f ree national community service\n‘Dial before you Dig’ be contacted on 1100 or by fax on 1200 65 2 077 regarding the location\nof underground services in order to prevent injury, personal liability and even death. Inquiries\nshould provide the property details and the nearest cross street/road.","stage":"general","stage_basis":"heading","page":34},{"label":"88","code":null,"number":"88","title":"","text":"Any necessary alterations to public utility installations ar e to be at the developer/demolisher’s\nexpense and to the requirements of both Council and any other r elevant authorities. Council\nand other service authorities should be contacted for specific requirements prior to the\ncommencement of any works.","stage":"general","stage_basis":"heading","page":34},{"label":"89","code":null,"number":"89","title":"","text":"Prior to commencing any construction works, the following pr ovisions of the Environmental\nPlanning and Assessment Act 1979 (NSW) (the ‘Act’) are to be complied with:\na) A Construction Certificate is to be obtained in accordance with Section 81A(2)(a) of the\nAct.\nb) A Principal Certifying Authority is to be appointed and Cou ncil is to be notified of the\nappointment in accordance with Section 81A(2)(b) of the Act.\nc) Council is to be given at least two days notice of the date intended for commencement\nof building works, in accordance with Section 81A(2)(c) of the Act.","stage":"general","stage_basis":"heading","page":34},{"label":"90","code":null,"number":"90","title":"","text":"A Construction Certificate application for this project is t o include a list of fire safety measures\nproposed to be installed in the building and/or on the land and include a separate list of any\nfire safety measures that already exist at the premises. The li sts must describe the extent,\ncapability and basis of design of each of the measures.","stage":"general","stage_basis":"heading","page":34},{"label":"91","code":null,"number":"91","title":"","text":"Prior to the occupation or use of a new building, or occupat ion or use of an altered portion of,\nor an extension to an existing building, an Occupation Certific ate is to be obtained from the\nPrincipal Certifying Authority appointed for the proposed devel opment. An application for an\nOccupation Certificate must contain the information set out in Clause 149 of the Environmental\nPlanning and Assessment Regulation 2000 (NSW).","stage":"general","stage_basis":"heading","page":34},{"label":"92","code":null,"number":"92","title":"","text":"A copy of the final Fire Safety Certificate (together with a copy of the current fire safety\nschedule) is to be given to the Commissioner of NSW Fire Brigad es and a further copy of the\nCertificate (together with a copy of the current fire safety sc hedule) is to be prominently\ndisplayed in the building.","stage":"general","stage_basis":"heading","page":34},{"label":"93","code":null,"number":"93","title":"","text":"An annual Fire Safety Statement in the form described in Cla use 175 of the Environmental\nPlanning and Assessment Regulation 2000 (NSW) is to be submitted to Council and a copy\n(together with a copy of the current fire safety schedule) is to be given to the Commissioner of\nNew South Wales Fire Brigades. A further copy of the Statement (together with a copy of the\ncurrent fire safety schedule) is to be prominently displayed in the building.","stage":"general","stage_basis":"heading","page":34},{"label":"94","code":null,"number":"94","title":"","text":"It is an offence under the provisions of the Protection of t he Environment Operations Act 1997\n(NSW) to act in a manner causing, or likely to cause, harm to the environment. Anyone allowing\nmaterial to enter a waterway or leaving material where it can be washed off-site may be subject\nto a penalty infringement notice (‘on-the-spot fine’) or prosecution.","stage":"general","stage_basis":"heading","page":35},{"label":"95","code":null,"number":"95","title":"","text":"Failure to comply with the conditions of consent constitutes a breach of the Environmental\nPlanning and Assessment Act 1979 (NSW), which may be subject to a penalty infringement\nnotice (‘on-the-spot fine’) or prosecution.","stage":"general","stage_basis":"heading","page":35},{"label":"96","code":null,"number":"96","title":"","text":"If archaeological deposits or relics not identified and cons idered in the supporting documents\nfor this consent are discovered, work must cease in the affecte d area(s) and the Heritage\nCouncil of NSW notified. Additional assessment and approval may be required prior to works\ncontinuing in the affected area(s) based on the nature of the discovery.\nNote: The Heritage Council of NSW can be contacted on 02 9873 8 500 or\nheritagemailbox@environment.nsw.gov.au. A ‘relic’ is any deposi t, object or material\nevidence that relates to the settlement of New South Wales, not being Aboriginal\nsettlement, and is of State or local significance. It is an offence under the provisions of\nthe Heritage Act 1977 (NSW) for a person to disturb or excavate any land on which the\nperson has discovered a relic except in accordance with a gazet ted exemption or an\nexcavation permit issued by the Heritage Council of NSW.\n(Inserted under MA2021/00192)\nSCHEDULE 2\nSUBSIDENCE ADVISORY NSW\n(Inserted under MA2021/00192)\nSCHEDULE 3\nREASONS FOR THE DETERMINATION & CONSIDERATION OF COMMUNITY VIEWS\nThe determination decision was reached for the following reasons:\n The proposed development, subject to the recommended conditions, is consistent with the objectives\nof the applicable environmental planning instruments, being; Newcastle Local Environmental Plan\n2012 and applicable State Environmental Planning Policies.\n The proposed development is, subject to the recommended conditions, consistent with the objectives\nof the Newcastle Development Control Plan 2012.\n The proposed development is considered to be of an appropriate scale and form for the site and the\ncharacter of the locality.\n The proposed development has appropriate management and mitigat ion of impacts through\nconditions of consent.\n The proposed development, subject to the recommended conditions , will not result in unacceptable\nadverse impacts upon the natural or built environments.\n The proposed development is a suitable and planned use of the site and its approval is within the public\ninterest.\n(Inserted under MA2021/00192)","stage":"general","stage_basis":"heading","page":35}]});
